				assertThrows(RepositoryException.class, connection::commit,
						"commit after failed prepare must not publish data that did not pass validation");
				connection.rollback();

				connection.begin(IsolationLevels.SNAPSHOT);
				connection.add(validPerson, RDF.TYPE, PERSON);
				connection.add(validPerson, NAME, VF.createLiteral("valid"));
				connection.commit();
